module pattern_sorter #(\n    parameter NUM_PATTERNS = 4,\n    parameter PATTERN_LENGTH = 8,\n    parameter DATA_WIDTH = 2,\n    parameter SCORE_WIDTH = 8,\n    parameter N_WIDTH = 20\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [N_WIDTH-1:0] n,\n    input wire [DATA_WIDTH*PATTERN_LENGTH-1:0] patterns_in [0:NUM_PATTERNS-1],\n    output reg done,\n    output reg [DATA_WIDTH*PATTERN_LENGTH-1:0] patterns_out [0:NUM_PATTERNS-1]\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_PREFIX = 3'd1;\n    localparam [2:0] SUM_BORDERS = 3'd2;\n    localparam [2:0] SORT = 3'd3;\n    localparam [2:0] DONE_STATE = 3'd4;\n\n    // Registers\n    reg [2:0] state, next_state;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] patterns_reg [0:NUM_PATTERNS-1];\n    reg [SCORE_WIDTH-1:0] scores [0:NUM_PATTERNS-1];\n    reg [SCORE_WIDTH-1:0] temp_scores [0:NUM_PATTERNS-1];\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] temp_patterns [0:NUM_PATTERNS-1];\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] current_pattern;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] prefix_func;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] border_mask;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] border_lengths;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] border_sum;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] pattern_index;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] i_reg, j_reg;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] k_reg;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] m_reg;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] temp_reg;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] swap_flag;\n    reg [DATA_WIDTH*PATTERN_LENGTH-1:0] cycle_count;\n    localparam [DATA_WIDTH*PATTERN_LENGTH-1:0] MAX_CYCLES = 8'd200;\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n            pattern_index <= 8'd0;\n            i_reg <= 8'd0;\n            j_reg <= 8'd0;\n            k_reg <= 8'd0;\n            m_reg <= 8'd0;\n            temp_reg <= 8'd0;\n            swap_flag <= 8'd0;\n            current_pattern <= 8'd0;\n            prefix_func <= 8'd0;\n            border_mask <= 8'd0;\n            border_lengths <= 8'd0;\n            border_sum <= 8'd0;\n            for (integer i = 0; i < NUM_PATTERNS; i = i + 1) begin\n                patterns_reg[i] <= 8'd0;\n                scores[i] <= 8'd0;\n                temp_scores[i] <= 8'd0;\n                temp_patterns[i] <= 8'd0;\n            end\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                done = 1'b0;\n                if (start) begin\n                    next_state = COMPUTE_PREFIX;\n                end\n            end\n            COMPUTE_PREFIX: begin\n                // Compute KMP prefix function for current pattern\n                if (i_reg < PATTERN_LENGTH) begin\n                    if (j_reg == 0 || current_pattern[i_reg] == current_pattern[j_reg]) begin\n                        prefix_func[i_reg] = j_reg + 1;\n                        i_reg = i_reg + 1;\n                        j_reg = j_reg + 1;\n                    end else begin\n                        j_reg = prefix_func[j_reg - 1];\n                    end\n                end else begin\n                    next_state = SUM_BORDERS;\n                end\n            end\n            SUM_BORDERS: begin\n                // Sum border lengths\n                if (k_reg < PATTERN_LENGTH) begin\n                    if (prefix_func[k_reg] > 0 && prefix_func[k_reg] == k_reg + 1) begin\n                        border_lengths[k_reg] = prefix_func[k_reg];\n                    end else begin\n                        border_lengths[k_reg] = 0;\n                    end\n                    k_reg = k_reg + 1;\n                end else begin\n                    // Sum all border lengths\n                    border_sum = 0;\n                    for (integer i = 0; i < PATTERN_LENGTH; i = i + 1) begin\n                        border_sum = border_sum + border_lengths[i];\n                    end\n                    scores[pattern_index] = border_sum;\n                    pattern_index = pattern_index + 1;\n                    if (pattern_index < NUM_PATTERNS) begin\n                        next_state = COMPUTE_PREFIX;\n                    end else begin\n                        next_state = SORT;\n                    end\n                end\n            end\n            SORT: begin\n                // Bubble sort patterns by score\n                if (m_reg < NUM_PATTERNS - 1) begin\n                    if (swap_flag == 0) begin\n                        m_reg = m_reg + 1;\n                    end\n                    if (temp_scores[m_reg] > temp_scores[m_reg + 1]) begin\n                        // Swap scores\n                        temp_reg = temp_scores[m_reg];\n                        temp_scores[m_reg] = temp_scores[m_reg + 1];\n                        temp_scores[m_reg + 1] = temp_reg;\n                        // Swap patterns\n                        temp_reg = temp_patterns[m_reg];\n                        temp_patterns[m_reg] = temp_patterns[m_reg + 1];\n                        temp_patterns[m_reg + 1] = temp_reg;\n                        swap_flag = 1;\n                    end else begin\n                        swap_flag = 0;\n                    end\n                end else begin\n                    next_state = DONE_STATE;\n                end\n            end\n            DONE_STATE: begin\n                done = 1'b1;\n                next_state = IDLE;\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Output assignment\n    always @(*) begin\n        for (integer i = 0; i < NUM_PATTERNS; i = i + 1) begin\n            patterns_out[i] = temp_patterns[i];\n        end\n    end\n\n    // Initialize patterns and scores on start\n    always @(posedge clk) begin\n        if (start) begin\n            for (integer i = 0; i < NUM_PATTERNS; i = i + 1) begin\n                patterns_reg[i] = patterns_in[i];\n                temp_patterns[i] = patterns_in[i];\n                scores[i] = 0;\n                temp_scores[i] = 0;\n            end\n            pattern_index = 0;\n            i_reg = 0;\n            j_reg = 0;\n            k_reg = 0;\n            m_reg = 0;\n            temp_reg = 0;\n            swap_flag = 0;\n            current_pattern = patterns_in[0];\n            prefix_func = 0;\n            border_mask = 0;\n            border_lengths = 0;\n            border_sum = 0;\n        end\n    end\n\n    // Update current pattern\n    always @(posedge clk) begin\n        if (state == COMPUTE_PREFIX && pattern_index < NUM_PATTERNS) begin\n            current_pattern = patterns_in[pattern_index];\n        end\n    end\n\n    // Cycle counter to prevent infinite loops\n    always @(posedge clk) begin\n        if (state != IDLE && state != DONE_STATE) begin\n            cycle_count = cycle_count + 1;\n            if (cycle_count >= MAX_CYCLES) begin\n                next_state = IDLE;\n            end\n        end else begin\n            cycle_count = 0;\n        end\n    end\n\nendmodule